mapper.select:
select cbfm.biz_function_id bizFunctionId ,id as msg_channel_id , smc.channel_code , smc.channel_name , smc.remark , cbfm.blacklist , cbfm.whitelist , ifnull(cbfm.priority, 1) as priority , ifnull(cbfm.is_enabled, false) as enabled from sys_msg_channel smc left join cf_biz_function_msg cbfm on cbfm.flag = 1 and cbfm.msg_channel_id = smc.id where smc.flag = 1 and smc.tenant_id = #{tenantId}
and cbfm.biz_function_id = #{bizFunctionId}
group by cbfm.biz_function_id, smc.id, smc.channel_code, smc.channel_name, smc.remark, cbfm.blacklist, cbfm.whitelist, cbfm.priority, cbfm.is_enabled order by cbfm.priority, smc.id
